import os, re, textwrap, collections, math
source='''from collections import Counter, deque

def _components(g, bg):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg or (r,c) in seen: continue
            v=g[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            for rr,cc in q:
                cells.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and g[nr][nc]==v:
                        seen.add((nr,nc)); q.append((nr,nc))
            out.append((v,cells))
    return out

def _sig(cells):
    variants=[]
    for flip in (0,1):
        for rot in range(4):
            pts=[]
            for r,c in cells:
                x,y=(r,-c if flip else c)
                for _ in range(rot): x,y=y,-x
                pts.append((x,y))
            mr=min(x for x,y in pts); mc=min(y for x,y in pts)
            variants.append(tuple(sorted((x-mr,y-mc) for x,y in pts)))
    return min(variants)

def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    objs=_components(g,bg)
    corners=[]
    for v,cells in objs:
        edges=set()
        for r,c in cells:
            if r==0: edges.add('T')
            if r==h-1: edges.add('B')
            if c==0: edges.add('L')
            if c==w-1: edges.add('R')
        if any({a,b}<=edges for a,b in (('T','L'),('T','R'),('B','L'),('B','R'))):
            corners.append((v,cells))
    if not corners: return g
    color,guide=max(corners,key=lambda x:len(x[1]))
    gc=(sum(r for r,c in guide)/len(guide),sum(c for r,c in guide)/len(guide))
    groups={}
    for v,cells in objs:
        if cells is guide: continue
        groups.setdefault(_sig(cells),[]).append((v,cells))
    repeated=[]
    for group in groups.values():
        if len(group)<2: continue
        # choose the occurrence farthest from the corner-shaped color marker
        v,cells=max(group,key=lambda item:(sum((sum(r for r,c in item[1])/len(item[1])-gc[0])**2+(sum(c for r,c in item[1])/len(item[1])-gc[1])**2 for _ in [0])))
        cr=sum(r for r,c in cells)/len(cells); cc=sum(c for r,c in cells)/len(cells)
        dist=(cr-gc[0])**2+(cc-gc[1])**2
        repeated.append((dist,v,cells))
    if repeated:
        _,_,target=max(repeated,key=lambda z:z[0])
        for r,c in target: g[r][c]=color
    return g
'''
